{
  "repository": "github.com/agronholm/exceptiongroup",
  "revision": "1df36aa5ff9314ced4968e682d15570251576e3b",
  "setup": [
    {
      "command": "pip install -e .[test] coverage",
      "workingDirectory": ".",
      "basis": "source-declaration",
      "sourceFiles": [".github/workflows/test.yml"]
    },
    {
      "command": "python3.12 -m pip install -e '.[test]'",
      "workingDirectory": ".",
      "basis": "adaptation",
      "sourceFiles": ["pyproject.toml"]
    },
    {
      "command": "pip install -e . pyright mypy",
      "workingDirectory": ".",
      "basis": "source-declaration",
      "sourceFiles": [".github/workflows/test.yml"]
    }
  ],
  "tests": [
    {
      "command": "python -m pytest {posargs}",
      "workingDirectory": ".",
      "basis": "source-declaration",
      "sourceFiles": ["pyproject.toml"]
    },
    {
      "command": "python3.12 -m pytest",
      "workingDirectory": ".",
      "basis": "adaptation",
      "sourceFiles": ["pyproject.toml"]
    },
    {
      "command": "coverage run -m pytest",
      "workingDirectory": ".",
      "basis": "source-declaration",
      "sourceFiles": [".github/workflows/test.yml"]
    },
    {
      "command": "pyright --verifytypes exceptiongroup --verbose",
      "workingDirectory": ".",
      "basis": "source-declaration",
      "sourceFiles": [".github/workflows/test.yml"]
    },
    {
      "command": "pyright tests/check_types.py",
      "workingDirectory": ".",
      "basis": "source-declaration",
      "sourceFiles": [".github/workflows/test.yml"]
    },
    {
      "command": "mypy tests/check_types.py",
      "workingDirectory": ".",
      "basis": "source-declaration",
      "sourceFiles": [".github/workflows/test.yml"]
    }
  ],
  "evidence": [
    {
      "path": "pyproject.toml",
      "lines": "19-23",
      "finding": "The declared minimum is Python >=3.7. Python <3.13, including 3.12, conditionally requires typing-extensions >=4.6.0."
    },
    {
      "path": "pyproject.toml",
      "lines": "30-33",
      "finding": "The test extra installs pytest >=6."
    },
    {
      "path": "pyproject.toml",
      "lines": "79-81",
      "finding": "Pytest defaults to -rsfE --tb=short --strict-config --strict-markers and searches tests/."
    },
    {
      "path": "pyproject.toml",
      "lines": "101-110",
      "finding": "Tox requires >=4.22, lists Python 3.7 through 3.15 plus PyPy, and its base environment installs the package editable with the test extra before running python -m pytest with optional positional arguments."
    },
    {
      "path": "pyproject.toml",
      "lines": "112-118",
      "finding": "The separate tox typing environment runs pyright verifytypes, pyright on tests/check_types.py, and mypy on that file; its dependencies include pyright 1.1.400 and mypy."
    },
    {
      "path": ".github/workflows/test.yml",
      "lines": "35-53",
      "finding": "CI's runtime test job covers Python 3.8–3.15 and PyPy 3.11, installs the editable project with test extra plus coverage, and runs coverage run -m pytest."
    },
    {
      "path": ".github/workflows/test.yml",
      "lines": "9-33",
      "finding": "Typing is a separate CI job over Python 3.8–3.15; it installs the package, pyright, and mypy, then runs three distinct type checks."
    },
    {
      "path": "pyproject.toml",
      "lines": "93-99",
      "finding": "The configuration comments clarify that CI's type tests do not type-check the package code itself."
    }
  ],
  "commandsExecuted": false,
  "executionEstablished": false,
  "toolchain": [
    "Python 3.12 target requested; not invoked",
    "tox >=4.22 declared",
    "pytest >=6 test extra",
    "typing-extensions >=4.6.0 when Python <3.13",
    "pyright ==1.1.400 and mypy in tox typing dependencies",
    "coverage in the CI runtime test setup"
  ],
  "coverageLimitations": [
    "A Python 3.12 runtime run covers only that interpreter. The package declares Python >=3.7 with no upper bound; tox lists 3.7–3.15 and PyPy, while the CI runtime matrix starts at 3.8.",
    "Pytest does not run the separate pyright and mypy checks. A 3.12 pytest result therefore says nothing about their outcome; CI runs them in a separate job across Python 3.8–3.15."
  ],
  "conflicts": [],
  "missingEvidence": [],
  "verificationRequired": [
    "After the change, install the edited checkout for Python 3.12 and run the proposed pytest command; these setup and test commands were not run.",
    "For a local typing result, install the type-checker dependencies and run all three separate typing commands; no typing checks were run.",
    "A 3.12-only run cannot verify the declared interpreter range; broader interpreter testing remains necessary for that claim."
  ]
}
